', status = 'READY', answer_type = 'NAT', nat_min = 0.83, nat_max = 0.85, difficulty = 2, answer_status = 'OFFICIAL_KEY', content_key = 'gate2016-s1-q20', origin = 'PYQ', updated_at = now() WHERE id = qid;
